css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .74); position: relative; overflow: hidden; border-radius: 8px; }
.loader .tub { position: absolute; inset: 0; border-radius: 8px; background: color-mix(in srgb, var(--accent) 14%, transparent); box-shadow: inset 0 0 0 3px color-mix(in srgb, var(--accent) 45%, transparent); }
.loader span { position: absolute; top: 12%; width: 7%; height: 56%; border-radius: 999px; background: linear-gradient(90deg, var(--accent-2), color-mix(in srgb, #000 12%, var(--accent-2))); animation: dish-rinse calc(var(--loader-speed) * 2) ease-in-out infinite; }
.loader span:nth-of-type(1) { left: 16%; }
.loader span:nth-of-type(2) { left: 30%; animation-delay: calc(var(--loader-speed) * .16); }
.loader span:nth-of-type(3) { left: 44%; animation-delay: calc(var(--loader-speed) * .32); }
.loader span:nth-of-type(4) { left: 58%; animation-delay: calc(var(--loader-speed) * .48); }
.loader span:nth-of-type(5) { left: 72%; animation-delay: calc(var(--loader-speed) * .64); }
.loader .arm { position: absolute; left: 50%; bottom: 12%; width: 64%; height: 6%; margin-left: -32%; border-radius: 3px; background: linear-gradient(90deg, transparent, var(--accent), transparent); animation: dish-arm calc(var(--loader-speed) * 1.2) linear infinite; }
.loader .arm::after { content: ''; position: absolute; left: 46%; top: -120%; width: 8%; height: 340%; border-radius: 3px; background: color-mix(in srgb, var(--accent) 55%, transparent); }
@keyframes dish-arm { to { transform: rotate(1turn); } }
@keyframes dish-rinse { 0%, 100% { transform: translateY(0); opacity: .7; } 50% { transform: translateY(-5%); opacity: 1; } }
